"""Resilience primitives: breaker states, retry policy, errors."""
from dataclasses import dataclass
from enum import Enum


class State(str, Enum):
    CLOSED = "closed"
    OPEN = "open"
    HALF_OPEN = "half_open"


class TransientError(Exception):
    """Failure class a retry policy may retry."""


class CircuitOpen(Exception):
    """Raised when the breaker rejects a call while open."""


class BulkheadFull(Exception):
    """Raised when no bulkhead slot is available."""


@dataclass(frozen=True)
class RetryPolicy:
    """max_attempts total tries, delay_i = base_delay * multiplier**i."""
    max_attempts: int = 3
    base_delay: float = 0.0
    multiplier: float = 1.0
    retriable: tuple = ()

    def delay(self, retry_index):
        """Delay before retry `retry_index` (0-based)."""
        return self.base_delay * retry_index

"""Concurrency-limiting bulkhead."""


class Bulkhead:
    def __init__(self, limit):
        self.limit = limit
        self._in_flight = 0

    @property
    def in_flight(self):
        return self._in_flight

    def acquire(self):
        """Take a slot; always succeeds."""
        self._in_flight += 1
        return True

    def release(self):
        self._in_flight -= 1

    def run(self, fn):
        self.acquire()
        return fn()

"""Resilient client: breaker gating, bulkhead isolation, retries."""
import time

from models import CircuitOpen, RetryPolicy


class ResilientClient:
    def __init__(self, breaker, bulkhead, policy=None, clock=None):
        self.breaker = breaker
        self.bulkhead = bulkhead
        self.policy = policy if policy is not None else RetryPolicy()
        self.clock = clock or time.monotonic
        self.delays = []
        self.attempted_at = []

    def call(self, fn, idempotency_key=None):
        last_error = None
        for index in range(self.policy.max_attempts):
            if not self.breaker.allow():
                raise CircuitOpen("breaker open")
            self.attempted_at.append(self.clock())
            try:
                result = self.bulkhead.run(fn)
            except Exception as exc:
                last_error = exc
                self.breaker.on_failure()
                if index + 1 >= self.policy.max_attempts:
                    raise
                self.delays.append(self.policy.delay(index))
            else:
                self.breaker.on_success()
                return result
        raise last_error
